import {dateUTC,secureIndex} from './core.mjs';
export const requireValue=(ok,message)=>{if(!ok)throw Error(message);};
export function parseNumbers(text){const raw=text.trim().split(/[\s,;]+/).filter(Boolean);requireValue(raw.length>0&&raw.length<=10000,'Enter between 1 and 10,000 numbers.');const a=raw.map(Number);requireValue(a.every(x=>Number.isFinite(x)&&Math.abs(x)<=1e100),'Use finite numbers up to 1e100, separated by spaces, commas or line breaks.');return a;}
export function statistics(values){const sorted=[...values].sort((a,b)=>a-b),count=values.length,sum=values.reduce((a,b)=>a+b,0),mean=sum/count,median=count%2?sorted[(count-1)/2]:(sorted[count/2-1]+sorted[count/2])/2,variance=values.reduce((a,b)=>a+(b-mean)**2,0)/count,frequencies=new Map();for(const x of values)frequencies.set(x,(frequencies.get(x)||0)+1);const largest=Math.max(...frequencies.values()),modes=largest>1?[...frequencies].filter(x=>x[1]===largest).map(x=>x[0]):[];return{count,sum,mean,median,min:sorted[0],max:sorted[count-1],range:sorted[count-1]-sorted[0],variance,populationSD:Math.sqrt(variance),sampleSD:count>1?Math.sqrt(variance*count/(count-1)):null,modes};}
const bigGCD=(a,b)=>{a=a<0n?-a:a;b=b<0n?-b:b;while(b)[a,b]=[b,a%b];return a;};
export function fraction(an,ad,bn,bd,op){const integer=s=>{requireValue(/^[+-]?\d{1,20}$/.test(String(s)),'Use integer fraction parts up to 20 digits.');return BigInt(s);};let a=integer(an),b=integer(ad),c=integer(bn),d=integer(bd);requireValue(b!==0n&&d!==0n,'Fraction denominators cannot be zero.');let numerator,denominator;if(op==='add'){numerator=a*d+c*b;denominator=b*d;}else if(op==='subtract'){numerator=a*d-c*b;denominator=b*d;}else if(op==='multiply'){numerator=a*c;denominator=b*d;}else{requireValue(c!==0n,'Cannot divide by a zero fraction.');numerator=a*d;denominator=b*c;}if(denominator<0n){numerator=-numerator;denominator=-denominator;}const g=bigGCD(numerator,denominator);numerator/=g;denominator/=g;return{text:denominator===1n?String(numerator):`${numerator}/${denominator}`,decimal:Number(numerator)/Number(denominator)};}
export function baseConvert(input,from,to){let s=input.trim().replace(/_/g,'');requireValue(s.length>0&&s.length<=260,'Use a whole number up to 256 digits.');const negative=s.startsWith('-');s=s.replace(/^[+-]/,'').replace(from===16?/^0x/i:from===2?/^0b/i:from===8?/^0o/i:/^$/,'');const chars='0123456789abcdef';requireValue(s.length>0&&s.length<=256&&[...s.toLowerCase()].every(c=>chars.indexOf(c)>=0&&chars.indexOf(c)<from),'The number contains a digit that is invalid for the selected base.');let n=0n;for(const c of s.toLowerCase())n=n*BigInt(from)+BigInt(chars.indexOf(c));if(negative)n=-n;return n.toString(to);}
export function randomIntegers(min,max,count,unique){requireValue(Number.isSafeInteger(min)&&Number.isSafeInteger(max)&&max>=min,'Use integer bounds with maximum at least minimum.');const span=max-min+1;requireValue(span<=4294967296,'Use a range containing at most 4,294,967,296 values.');requireValue(count>=1&&count<=1000&&Number.isInteger(count),'Generate between 1 and 1,000 values.');requireValue(!unique||count<=span,'A unique selection cannot exceed the size of its range.');if(!unique)return Array.from({length:count},()=>min+secureIndex(span));const set=new Set();while(set.size<count)set.add(min+secureIndex(span));return [...set];}
export function durationSeconds(s){const m=s.trim().match(/^(\d{1,8}):(\d{1,2})(?::(\d{1,2}))?$/);requireValue(m&&+m[2]<60&&+(m[3]||0)<60,'Use HH:MM or HH:MM:SS with minutes and seconds from 0 to 59.');return +m[1]*3600 + +m[2]*60 + +(m[3]||0);}
export function formatDuration(seconds){const sign=seconds<0?'-':'';seconds=Math.abs(Math.round(seconds));return sign+[Math.floor(seconds/3600),Math.floor(seconds/60)%60,seconds%60].map(x=>String(x).padStart(2,'0')).join(':');}
export function weightedGPA(input,scale){const rows=input.trim().split(/\r?\n/).filter(x=>x.trim()).map(line=>{const parts=line.trim().split(/[\s,;]+/).map(Number);requireValue(parts.length===2&&parts.every(Number.isFinite),'Use one grade-points, credits pair per line.');const [points,credits]=parts;requireValue(points>=0&&points<=scale&&credits>0&&credits<=1e12,'Grade points must fit the scale; credits must be positive and at most one trillion.');return{points,credits};});requireValue(rows.length>0&&rows.length<=1000,'Enter 1 to 1,000 course rows.');const credits=rows.reduce((s,r)=>s+r.credits,0);return{gpa:rows.reduce((s,r)=>s+r.points*r.credits,0)/credits,credits,courses:rows.length};}
export function studyPlan(total,focus,rest){requireValue(total>=focus&&focus>0&&rest>=0,'Available time must include at least one complete focus block.');let t=0,blocks=0,focusMinutes=0,breakMinutes=0,lines=[];while(t+focus<=total){lines.push({type:'Focus',start:t,end:t+focus});t+=focus;blocks++;focusMinutes+=focus;if(t+rest+focus<=total&&rest){lines.push({type:'Break',start:t,end:t+rest});t+=rest;breakMinutes+=rest;}else if(t+focus>total)break;}return{lines,blocks,focusMinutes,breakMinutes,unused:total-t};}
export function dateOffset(start,days){const d=dateUTC(start);d.setUTCDate(d.getUTCDate()+days);requireValue(Number.isFinite(+d)&&d.getUTCFullYear()>=1&&d.getUTCFullYear()<=9999,'The resulting date must be between years 0001 and 9999.');return d.toISOString().slice(0,10);}
export function businessDays(start,end,holidays=[]){const a=dateUTC(start),b=dateUTC(end);requireValue(a<=b,'End date must be on or after start date.');requireValue((b-a)/86400000<=36600,'Use a range of 100 years or less.');const excluded=new Set(holidays),work=d=>d.getUTCDay()!==0&&d.getUTCDay()!==6&&!excluded.has(d.toISOString().slice(0,10));let count=0;for(const d=new Date(a);d<=b;d.setUTCDate(d.getUTCDate()+1))if(work(d))count++;return count;}
export function addBusinessDays(start,count,holidays=[]){requireValue(Number.isInteger(count)&&count>=0&&count<=10000,'Add between 0 and 10,000 working days.');const d=dateUTC(start),excluded=new Set(holidays);let left=count,iterations=0;while(left>0){d.setUTCDate(d.getUTCDate()+1);requireValue(++iterations<100000,'Too many excluded days.');if(d.getUTCDay()!==0&&d.getUTCDay()!==6&&!excluded.has(d.toISOString().slice(0,10)))left--;}requireValue(d.getUTCFullYear()<=9999,'The resulting date must be before year 10000.');return d.toISOString().slice(0,10);}
export function csvRecords(text,delimiter=','){requireValue(text.length<=2000000,'Use a CSV input smaller than two million characters.');text=text.replace(/^\uFEFF/,'').replace(/\r\n/g,'\n').replace(/\r/g,'\n');const rows=[];let row=[],field='',quoted=false,afterQuote=false;function endField(){row.push(field);field='';afterQuote=false;}function endRow(){endField();rows.push(row);row=[];requireValue(rows.length<=10001,'Convert up to 10,000 data rows.');}for(let i=0;i<text.length;i++){const c=text[i];if(quoted){if(c==='"'){if(text[i+1]==='"'){field+='"';i++;}else{quoted=false;afterQuote=true;}}else field+=c;}else if(c==='"'){requireValue(field===''&&!afterQuote,'A quoted CSV field must begin with a quote.');quoted=true;}else if(c===delimiter)endField();else if(c==='\n')endRow();else{requireValue(!afterQuote||c===' '||c==='\t','Unexpected content after a closing CSV quote.');if(!afterQuote)field+=c;}}requireValue(!quoted,'Close the quoted CSV field.');if(field!==''||row.length||afterQuote)endRow();requireValue(rows.length>=2,'Include a header row and at least one data row.');const headers=rows.shift().map(x=>x.trim());requireValue(headers.every(Boolean)&&new Set(headers).size===headers.length,'Headers must be nonempty and unique.');return rows.filter(r=>r.some(x=>x!=='')).map(r=>{requireValue(r.length===headers.length,'Each data row must have the same number of columns as the header.');return Object.fromEntries(headers.map((h,i)=>[h,r[i]]));});}
export function jsonDifference(a,b){const diffs=[];let visited=0;function walk(x,y,path,depth=0){requireValue(depth<=50&&++visited<=50000,'Use smaller or less deeply nested JSON values.');if(diffs.length>=300)return;if(Object.is(x,y))return;const xo=x!==null&&typeof x==='object',yo=y!==null&&typeof y==='object';if(!xo||!yo||Array.isArray(x)!==Array.isArray(y)){diffs.push({path,type:'changed',before:x,after:y});return;}const keys=new Set([...Object.keys(x),...Object.keys(y)]);for(const k of keys){const p=Array.isArray(x)?`${path}[${k}]`:`${path}[${JSON.stringify(k)}]`;if(!Object.hasOwn(x,k))diffs.push({path:p,type:'added',after:y[k]});else if(!Object.hasOwn(y,k))diffs.push({path:p,type:'removed',before:x[k]});else walk(x[k],y[k],p,depth+1);if(diffs.length>=300)break;}}walk(a,b,'$');return diffs;}
const commonEntities={amp:'&',lt:'<',gt:'>',quot:'"',apos:"'",nbsp:'\u00a0',copy:'©',reg:'®',trade:'™',mdash:'—',ndash:'–',hellip:'…',euro:'€',pound:'£',yen:'¥'};
export function decodeEntities(s){return s.replace(/&(#x[0-9a-f]+|#\d+|[a-z]+);/gi,(all,name)=>{if(name[0]!=='#')return commonEntities[name.toLowerCase()]??all;const code=name[1].toLowerCase()==='x'?parseInt(name.slice(2),16):+name.slice(1);return code>=0&&code<=0x10ffff&&!(code>=0xd800&&code<=0xdfff)?String.fromCodePoint(code):all;});}
export function makeSlug(s,ascii=false){if(ascii)s=s.normalize('NFKD').replace(/[\u0300-\u036f]/g,'').replace(/[^a-zA-Z0-9\s_-]/g,'');return s.toLowerCase().replace(/[^\p{L}\p{M}\p{N}\s_-]/gu,'').trim().replace(/[\s_-]+/g,'-').replace(/^-+|-+$/g,'');}
export function fluidClamp(min,max,minViewport,maxViewport,root=16){requireValue(max>=min&&maxViewport>minViewport&&root>0,'Maximum size must be at least minimum, and maximum viewport must exceed minimum.');const slope=(max-min)/(maxViewport-minViewport),intercept=min-slope*minViewport;return `font-size: clamp(${+(min/root).toFixed(5)}rem, ${+(intercept/root).toFixed(5)}rem + ${+(slope*100).toFixed(5)}vw, ${+(max/root).toFixed(5)}rem);`;}
export function hexHSL(hex){requireValue(/^#[0-9a-f]{6}$/i.test(hex),'Use a six-digit HEX color.');const [r,g,b]=hex.slice(1).match(/../g).map(s=>parseInt(s,16)/255),max=Math.max(r,g,b),min=Math.min(r,g,b),delta=max-min,l=(max+min)/2;let h=0,s=0;if(delta){s=delta/(1-Math.abs(2*l-1));h=max===r?((g-b)/delta)%6:max===g?(b-r)/delta+2:(r-g)/delta+4;h=(h*60+360)%360;}return{h,s,l};}
export function hslHex(h,s,l){h=(h%360+360)%360;const a=s*Math.min(l,1-l),f=n=>{const k=(n+h/30)%12;return l-a*Math.max(-1,Math.min(k-3,9-k,1));};return '#'+[f(0),f(8),f(4)].map(x=>Math.round(x*255).toString(16).padStart(2,'0')).join('');}
export function paletteColors(hex,kind){const {h,s,l}=hexHSL(hex),offsets=kind==='complementary'?[0,180]:kind==='triadic'?[0,120,240]:kind==='tetradic'?[0,90,180,270]:[-30,0,30];return offsets.map(x=>hslHex(h+x,s,l));}
